{"content":""""A tiny shopping cart with a few bugs in it. examples/showcase/bugfix.py fixes a copy."""

from dataclasses import dataclass, field

FREE_SHIPPING_FROM = 50.00  # free shipping when the discounted subtotal reaches this
SHIPPING = 4.99
TAX_RATE = 0.14


@dataclass
class Item:
    name: str
    price: float
    qty: int = 1


@dataclass
class Cart:
    items: list[Item] = field(default_factory=list)
    coupon_percent: float = 0  # 10 means 10% off

    def subtotal(self) -> float:
        """Calculate the subtotal counting quantity of each item."""
        return sum(item.price * item.qty for item in self.items)

    def discount(self) -> float:
        """Calculate discount as a percentage of the subtotal."""
        return self.subtotal() * (self.coupon_percent / 100.0)

    def shipping(self) -> float:
        """Shipping is free when the discounted subtotal reaches the threshold.
        Otherwise a flat shipping fee applies.
        """
        discounted_subtotal = self.subtotal() - self.discount()
        # Free shipping when discounted subtotal is greater than or equal to threshold
        return 0.0 if discounted_subtotal >= FREE_SHIPPING_FROM else SHIPPING

    def total(self) -> float:
        """Calculate total cost including tax and shipping, rounded to nearest cent.
        An empty cart costs nothing.
        """
        if not self.items:
            return 0.0
        taxed = (self.subtotal() - self.discount()) * (1 + TAX_RATE)
        total_amount = taxed + self.shipping()
        # Round to nearest cent
        return round(total_amount, 2)
