from dataclasses import dataclass, field
from decimal import Decimal, ROUND_HALF_UP

FREE_SHIPPING_FROM = Decimal('50.00')  # free shipping when the discounted subtotal reaches this
SHIPPING = Decimal('4.99')
TAX_RATE = Decimal('0.14')


@dataclass
class Item:
    name: str
    price: Decimal
    qty: int = 1


@dataclass
class Cart:
    items: list[Item] = field(default_factory=list)
    coupon_percent: Decimal = Decimal('0')  # 10 means 10% off

    def subtotal(self) -> Decimal:
        """Calculate the subtotal counting quantity of each item."""
        return sum(item.price * item.qty for item in self.items)

    def discount(self) -> Decimal:
        """Calculate discount as a percentage of the subtotal."""
        return self.subtotal() * (self.coupon_percent / Decimal('100'))

    def shipping(self) -> Decimal:
        """Shipping is free when the discounted subtotal reaches the threshold.
        Otherwise a flat shipping fee applies.
        """
        discounted_subtotal = self.subtotal() - self.discount()
        return Decimal('0') if discounted_subtotal >= FREE_SHIPPING_FROM else SHIPPING

    def total(self) -> Decimal:
        """Calculate total cost including tax and shipping, rounded to nearest cent.
        An empty cart costs nothing.
        """
        if not self.items:
            return Decimal('0')
        taxed = (self.subtotal() - self.discount()) * (Decimal('1') + TAX_RATE)
        total_amount = taxed + self.shipping()
        # Round to nearest cent using ROUND_HALF_UP
        return total_amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
